
  function switchTab(tab) {
    document.querySelectorAll('.tab-section').forEach(s => s.classList.remove('active'));
    document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
    var section = document.getElementById('tab-' + tab);
    var btn = document.getElementById('btn-' + tab);
    if (section) section.classList.add('active');
    if (btn) btn.classList.add('active');
    window.scrollTo({top: 0, behavior: 'smooth'});
  }
  const btn = document.getElementById("themeToggle");

  btn.addEventListener("click", () => {
    document.documentElement.classList.toggle("light");
    // guardar preferencia
    if (document.documentElement.classList.contains("light")) {
      localStorage.setItem("theme", "light");
    } else {
      localStorage.setItem("theme", "dark");
    }
  });

  // cargar preferencia guardada
  if (localStorage.getItem("theme") === "light") {
    document.documentElement.classList.add("light");
  }

(function(){
 const cards=[...document.querySelectorAll('#tab-services .card')];
 const search=document.getElementById('studySearch'), favoritesBtn=document.getElementById('favoritesFilter');
 const count=document.getElementById('studyCount'), empty=document.getElementById('emptyStudy');
 const stored=(()=>{try{return JSON.parse(localStorage.getItem('aws-study-favorites')||'[]')}catch{return []}})();
 const favorites=new Set(Array.isArray(stored)?stored:[]);
 const normalize=s=>(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const keys=new Map();
 cards.forEach((card,index)=>{
   const title=card.querySelector('.card-name')?.textContent?.trim()||'Tarjeta '+(index+1);
   const category=card.closest('.category')?.id||'general';
   const key=category+'::'+title+'::'+index;
   keys.set(card,key);
   const head=card.querySelector('.card-head');
   if(head){
     const button=document.createElement('button');
     button.className='bookmark-card';button.type='button';button.title='Guardar en favoritos';
     button.setAttribute('aria-label','Guardar '+title+' en favoritos');
     function render(){const on=favorites.has(key);button.textContent=on?'★':'☆';button.setAttribute('aria-pressed',String(on))}
     button.addEventListener('click',()=>{favorites.has(key)?favorites.delete(key):favorites.add(key);try{localStorage.setItem('aws-study-favorites',JSON.stringify([...favorites]))}catch{}render();apply()});
     head.append(button);render();
   }
 });
 function apply(){
   const query=normalize(search.value.trim()), onlyFav=favoritesBtn.getAttribute('aria-pressed')==='true';
   let shown=0;
   cards.forEach(card=>{
     const visible=(!query||normalize(card.textContent).includes(query))&&(!onlyFav||favorites.has(keys.get(card)));
     card.hidden=!visible;card.style.display=visible?'':'none';if(visible)shown++;
   });
   document.querySelectorAll('#tab-services .category').forEach(section=>{
     const visible=[...section.querySelectorAll('.card')].some(card=>!card.hidden);
     section.hidden=!visible;section.style.display=visible?'':'none';
   });
   count.textContent=shown+' de '+cards.length+' tarjetas visibles · '+favorites.size+' favoritas';
   empty.style.display=shown?'none':'block';
 }
 search.addEventListener('input',apply);
 favoritesBtn.addEventListener('click',()=>{const pressed=favoritesBtn.getAttribute('aria-pressed')==='true';favoritesBtn.setAttribute('aria-pressed',String(!pressed));favoritesBtn.textContent=pressed?'☆ Mis favoritos':'★ Mostrando favoritos';apply()});
 document.getElementById('clearFilters').addEventListener('click',()=>{search.value='';favoritesBtn.setAttribute('aria-pressed','false');favoritesBtn.textContent='☆ Mis favoritos';apply()});
 function progress(){const root=document.documentElement;const range=root.scrollHeight-root.clientHeight;document.getElementById('readingProgress').style.width=(range?100*scrollY/range:0)+'%'}
 window.addEventListener('scroll',progress,{passive:true});window.addEventListener('resize',progress);progress();apply();
 const top=document.createElement('button');top.className='study-backtop';top.type='button';top.textContent='↑ Arriba';top.setAttribute('aria-label','Volver al inicio');top.addEventListener('click',()=>window.scrollTo({top:0,behavior:'smooth'}));document.body.append(top);
 const theme=document.getElementById('themeToggle');
 function labelTheme(){theme.textContent=document.documentElement.classList.contains('light')?'🌙 Modo oscuro':'☀️ Modo claro'}
 theme.addEventListener('click',labelTheme);labelTheme();
})();



const STUDY_BANK = [{"name": "Amazon Athena", "category": "Análisis (Analytics)", "tagline": "SQL serverless sobre S3", "concept": "Servicio de consultas interactivas serverless que permite analizar datos directamente en Amazon S3 usando SQL estándar (compatible con ANSI SQL). No requiere infraestructura, no hay servidores que gestionar.", "tip": "Athena = SQL + S3 sin servidores. Cobro por TB escaneado. Parquet/ORC reduce costos hasta 90%. Integra con Glue Data Catalog para esquemas."}, {"name": "Amazon EMR", "category": "Análisis (Analytics)", "tagline": "Elastic MapReduce — Big Data en clúster", "concept": "Plataforma administrada de clúster para procesamiento de Big Data. Ejecuta frameworks distribuidos como Apache Hadoop, Spark, Hive, HBase, Flink, Presto sobre EC2, EKS o de forma serverless.", "tip": "EMR = Big Data con Spark/Hadoop administrado. EMR Serverless elimina gestión de clústeres. Spot en nodos Task para máximo ahorro. Para procesar terabytes sin gestionar infraestructura manual."}, {"name": "AWS Glue", "category": "Análisis (Analytics)", "tagline": "ETL serverless y catálogo de datos", "concept": "Servicio de integración de datos serverless. Descubre, prepara y combina datos para análisis, ML e ingeniería de datos. Incluye el Glue Data Catalog (repositorio central de metadata).", "tip": "Glue = ETL serverless. Glue Data Catalog es el \"directorio\" central que usan Athena, EMR y Redshift Spectrum. Crawlers descubren esquemas automáticamente. DataBrew para transformaciones sin código."}, {"name": "Amazon Kinesis", "category": "Análisis (Analytics)", "tagline": "Streaming de datos en tiempo real", "concept": "Suite de servicios para recolectar, procesar y analizar datos en streaming en tiempo real. Permite tomar decisiones con datos de milisegundos de latencia.", "tip": "Kinesis = streaming en tiempo real. Firehose = más simple, sin código, entrega a S3/Redshift. Data Streams = más control, shards, consumidores propios. 1 shard = 1MB/s entrada."}, {"name": "Amazon OpenSearch Service", "category": "Análisis (Analytics)", "tagline": "Búsqueda y análisis de logs", "concept": "Servicio administrado de OpenSearch (antes Elasticsearch). Permite búsqueda de texto completo, análisis de logs y monitoreo en tiempo real. Incluye Dashboards (antes Kibana) para visualización.", "tip": "OpenSearch = búsqueda full-text + análisis de logs. Sucesor de Elasticsearch en AWS. Serverless tiene mínimo alto ($345/mes). Integra con Kinesis Firehose y CloudWatch Logs."}, {"name": "Amazon QuickSight", "category": "Análisis (Analytics)", "tagline": "BI y visualización de datos serverless", "concept": "Servicio de inteligencia de negocios (BI) serverless escalable. Permite crear y publicar dashboards interactivos que pueden embeberse en aplicaciones. Motor SPICE para aceleración de consultas en memoria.", "tip": "QuickSight = BI serverless de AWS. SPICE = caché en memoria. Reader = barato, solo ve. Author = crea contenido. Para dashboards ejecutivos."}, {"name": "Amazon Redshift", "category": "Análisis (Analytics)", "tagline": "Data warehouse a escala de petabytes", "concept": "Data warehouse en la nube totalmente administrado y a escala de petabytes. Basado en PostgreSQL, usa almacenamiento columnar y procesamiento masivo paralelo (MPP) para consultas analíticas muy rápidas.", "tip": "Redshift = data warehouse OLAP (no OLTP). RA3 separa cómputo de almacenamiento. Serverless para cargas variables. Spectrum para consultar S3 sin cargar datos. Almacenamiento columnar = consultas analíticas ultrarrápidas."}, {"name": "Amazon EventBridge", "category": "Integración de Aplicaciones", "tagline": "Bus de eventos serverless", "concept": "Bus de eventos serverless que conecta aplicaciones con datos de servicios AWS, SaaS y aplicaciones propias. Permite construir arquitecturas event-driven con reglas de enrutamiento.", "tip": "EventBridge = enrutador de eventos serverless. Antes: CloudWatch Events. Eventos de AWS al bus Default son GRATIS. Scheduler reemplaza cron jobs. Para integración con SaaS usa Partner Event Sources."}, {"name": "Amazon SNS", "category": "Integración de Aplicaciones", "tagline": "Simple Notification Service — Pub/Sub", "concept": "Servicio de mensajería pub/sub totalmente administrado. Envía notificaciones desde publicadores a múltiples suscriptores (fanout). Soporta push a móviles, SMS, email, Lambda, SQS, HTTPS.", "tip": "SNS = pub/sub, 1 a muchos (push). SQS = cola, 1 a 1 (pull). SNS FIFO solo acepta SQS FIFO como suscriptor. Patrón Fanout: 1 SNS topic → múltiples SQS queues para procesamiento paralelo."}, {"name": "Amazon SQS", "category": "Integración de Aplicaciones", "tagline": "Simple Queue Service — Cola de mensajes", "concept": "Servicio de colas de mensajes totalmente administrado. Desacopla y escala microservicios, sistemas distribuidos y aplicaciones serverless. Garantiza entrega al menos una vez.", "tip": "SQS desacopla productor de consumidor. Standard = alto throughput, orden best-effort. FIFO = orden exacto, exactly-once (para pagos, inventario). Dead Letter Queue para mensajes que fallan repetidamente. Long Polling reduce costos."}, {"name": "AWS Step Functions", "category": "Integración de Aplicaciones", "tagline": "Orquestación de flujos de trabajo", "concept": "Servicio de orquestación serverless que combina funciones Lambda y otros servicios AWS en flujos de trabajo visuales (máquinas de estado). Define lógica de negocio sin código repetitivo.", "tip": "Step Functions = orquestador visual de servicios AWS. Standard (hasta 1 año, exactamente-una-vez) para procesos de negocio. Express (hasta 5 min, alta frecuencia) para IoT/streaming. Maneja reintentos, errores y paralelismo."}, {"name": "Amazon Connect", "category": "Aplicaciones Empresariales", "tagline": "Contact center en la nube", "concept": "Contact center como servicio (CCaaS) en la nube, omnicanal. Permite configurar centros de llamadas en minutos sin hardware especializado. Integra voz, chat, tareas y analítica.", "tip": "Connect = contact center en AWS, pay-per-minute. Sin licencias costosas. Contact Lens analiza llamadas con ML (sentimiento, temas). Integra con Amazon Lex para IVR inteligente y con CRM via Lambda."}, {"name": "Amazon SES", "category": "Aplicaciones Empresariales", "tagline": "Simple Email Service", "concept": "Servicio de envío y recepción de correo electrónico a escala, orientado a desarrolladores y empresas. Soporta emails transaccionales, de marketing y masivos con alta entregabilidad.", "tip": "SES = emails masivos transaccionales y marketing. 62K emails/mes GRATIS si envías desde EC2/Lambda. Sandbox mode al inicio (solo destinatarios verificados). Diferente de SNS email (para notificaciones simples de sistema)."}, {"name": "AWS Budgets", "category": "Administración Financiera en la Nube", "tagline": "Presupuestos y alertas de costos", "concept": "Permite definir presupuestos personalizados de costos y uso, y recibir alertas cuando el gasto real o previsto supera los umbrales establecidos. Puede disparar acciones automáticas.", "tip": "Budgets = alertas PROACTIVAS de gasto. 2 presupuestos gratis para siempre. Alerta con % del presupuesto (ej: avisa al 80%). Budget Actions para respuesta automática. Tipos: Costo, Uso, Reservas, Savings Plans."}, {"name": "Informes de Costo y Uso (CUR)", "category": "Administración Financiera en la Nube", "tagline": "Datos granulares de facturación", "concept": "Genera informes detallados (CSV/Parquet) de todos los costos y uso de AWS, desglosados por servicio, recurso, etiqueta, hora. Es la fuente más completa de datos de facturación.", "tip": "CUR = fuente más granular de costos (gratis de generar). Se entrega a S3, se consulta con Athena. Granularidad por hora, recurso y etiqueta. Ideal para chargeback por departamento usando Cost Allocation Tags."}, {"name": "AWS Cost Explorer", "category": "Administración Financiera en la Nube", "tagline": "Visualiza y analiza costos", "concept": "Herramienta visual interactiva para explorar, entender y gestionar costos y uso de AWS. Ofrece vistas predefinidas, filtros por servicio/región/etiqueta y previsiones de hasta 12 meses.", "tip": "Cost Explorer = visualización histórica + previsiones (gratis en consola). Budgets = alertas proactivas. CUR = datos raw granulares. Cost Explorer recomienda Reserved Instances y Savings Plans basado en tu historial."}, {"name": "AWS Marketplace", "category": "Administración Financiera en la Nube", "tagline": "Catálogo de software de terceros", "concept": "Catálogo digital con miles de soluciones de software de terceros listas para usar en AWS (AMIs, SaaS, contenedores, datos). Facturación consolidada con la cuenta AWS.", "tip": "Marketplace = software de terceros verificado, listo para AWS. Cobro en factura AWS. BYOL = traes tu licencia existente (Oracle, SQL Server). Ideal para soluciones de seguridad, networking y herramientas empresariales certificadas."}, {"name": "AWS Batch", "category": "Computación", "tagline": "Procesamiento por lotes administrado", "concept": "Servicio para ejecutar trabajos de computación por lotes (batch) a cualquier escala. Aprovisiona dinámicamente EC2/Spot según la demanda. Elimina la gestión manual de infraestructura HPC.", "tip": "Batch = jobs de larga duración (Lambda tiene límite de 15 min). El servicio Batch es GRATIS — pagas EC2/Fargate. Spot Instances para máximo ahorro en cargas tolerantes a interrupción. HPC, renderizado, bioinformática."}, {"name": "Amazon EC2", "category": "Computación", "tagline": "Elastic Compute Cloud — Servidores virtuales", "concept": "Servicio central de cómputo de AWS. Proporciona capacidad de cómputo redimensionable en la nube mediante instancias virtuales (VMs). Control total sobre el SO y configuración.", "tip": "EC2 = IaaS. On-Demand (sin compromiso), Reserved (máximo ahorro, 1-3 años), Spot (barato, interrumpible), Dedicated Host (licencias BYOL). Stop = datos EBS persisten. Terminate = instancia + EBS root eliminados."}, {"name": "AWS Elastic Beanstalk", "category": "Computación", "tagline": "PaaS — Deploy fácil de apps", "concept": "Plataforma como Servicio (PaaS) que automatiza el despliegue y escalado de aplicaciones web. El desarrollador solo sube el código; AWS gestiona la infraestructura subyacente (EC2, Load Balancer, Auto Scaling).", "tip": "Beanstalk = PaaS GRATIS (pagas EC2/ELB/RDS subyacente). Soporta Java, Python, Node.js, .NET, Ruby, Go, Docker, PHP. Retiene acceso completo a la infra. No es serverless (corre en EC2 gestionado automáticamente)."}, {"name": "Amazon Lightsail", "category": "Computación", "tagline": "VPS simplificado para principiantes", "concept": "Forma más simple de lanzar y gestionar servidores virtuales en AWS. Ofrece paquetes todo-en-uno con VPS, SSD, DNS y IP estática a precio fijo mensual predecible.", "tip": "Lightsail = VPS precio fijo predecible (desde $3.50/mes). Más simple que EC2, menos flexible. Para usuarios nuevos en AWS o cargas pequeñas y predecibles. Similar a DigitalOcean o Linode."}, {"name": "AWS Outposts", "category": "Computación", "tagline": "AWS en tus instalaciones físicas", "concept": "Infraestructura física de AWS instalada en el centro de datos del cliente (on-premises). Permite ejecutar servicios AWS con las mismas herramientas, APIs y consola que en la nube, localmente.", "tip": "Outposts = infraestructura AWS física en tus instalaciones. Mismas APIs on-premises que en la nube. Para requisitos regulatorios de localización de datos o latencia ultra-baja. Rack completo (42U) o servidores individuales (1U/2U)."}, {"name": "Amazon ECR", "category": "Contenedores", "tagline": "Elastic Container Registry", "concept": "Registro de contenedores Docker totalmente administrado y seguro. Almacena, gestiona y despliega imágenes de contenedores. Integración nativa con ECS, EKS y CodePipeline.", "tip": "ECR = registro privado de imágenes Docker de AWS. Integra con IAM, ECS y EKS nativamente. Escaneo automático de vulnerabilidades CVE. Pull dentro de la misma región es gratis. Sin ECR necesitarías Docker Hub externo."}, {"name": "Amazon ECS", "category": "Contenedores", "tagline": "Elastic Container Service", "concept": "Servicio de orquestación de contenedores Docker totalmente administrado. Ejecuta y escala contenedores en EC2 o con Fargate (serverless). Profundamente integrado con el ecosistema AWS.", "tip": "ECS = orquestación AWS nativa (más simple que EKS, sin cargo por el servicio con EC2). Con Fargate es serverless. Task Definition = blueprint del contenedor. Service = mantiene N tasks corriendo siempre."}, {"name": "Amazon EKS", "category": "Contenedores", "tagline": "Elastic Kubernetes Service", "concept": "Servicio Kubernetes administrado. AWS gestiona el control plane de Kubernetes. Permite ejecutar cargas de trabajo Kubernetes sin gestionar los nodos maestros. Compatible con herramientas estándar de Kubernetes.", "tip": "EKS = Kubernetes administrado ($0.10/hora por clúster). ECS = orquestación AWS nativa (sin cargo con EC2). Si ya usas K8s → EKS. Empezando desde cero → ECS más simple. Ambos soportan Fargate para serverless."}, {"name": "Amazon Aurora", "category": "Bases de Datos", "tagline": "Base de datos relacional cloud-native", "concept": "Motor de base de datos relacional compatible con MySQL y PostgreSQL, construido para la nube. Hasta 5x más rápido que MySQL estándar y 3x más rápido que PostgreSQL. Almacenamiento auto-escalable hasta 128 TB.", "tip": "Aurora = RDS premium (más rápido, más resiliente, más costoso). 6 copias en 3 AZs automático. Compatible MySQL/PostgreSQL. Serverless v2 para cargas impredecibles. Global Database para DR cross-region con RPO de ~1 segundo."}, {"name": "Amazon DocumentDB", "category": "Bases de Datos", "tagline": "Base de datos de documentos compatible MongoDB", "concept": "Servicio de base de datos de documentos totalmente administrado, compatible con MongoDB. Almacena datos en formato JSON. Escala de forma independiente cómputo y almacenamiento.", "tip": "DocumentDB = MongoDB administrado en AWS. NoSQL de documentos JSON. Si el examen menciona MongoDB → DocumentDB. No confundir con DynamoDB (clave-valor) ni Neptune (grafos)."}, {"name": "Amazon DynamoDB", "category": "Bases de Datos", "tagline": "NoSQL serverless de alto rendimiento", "concept": "Base de datos NoSQL (clave-valor y documentos) totalmente administrada y serverless. Ofrece latencia de un dígito en milisegundos a cualquier escala. Escala automáticamente sin tiempo de inactividad.", "tip": "DynamoDB = NoSQL serverless con Free Tier permanente (25 GB + 25 WCU + 25 RCU). Latencia <10ms garantizada. Global Tables = activo-activo multi-región. DAX para microsegundos. On-Demand para tráfico impredecible."}, {"name": "Amazon ElastiCache", "category": "Bases de Datos", "tagline": "Caché en memoria administrado", "concept": "Servicio de caché en memoria totalmente administrado. Soporta Redis y Memcached. Mejora drásticamente el rendimiento de aplicaciones cargando datos frecuentes desde memoria.", "tip": "ElastiCache = reducir latencia y carga en RDS/Aurora. Redis para funcionalidades avanzadas (persistencia, pub/sub, sorted sets). Memcached para caché simple sin persistencia. Si el examen pregunta cómo acelerar lecturas de BD → ElastiCache."}, {"name": "Amazon Neptune", "category": "Bases de Datos", "tagline": "Base de datos de grafos", "concept": "Servicio de base de datos de grafos totalmente administrado. Optimizado para almacenar y navegar relaciones complejas entre datos. Soporta Gremlin, SPARQL y openCypher.", "tip": "Neptune = grafos. Palabras clave: relaciones complejas, red social, fraude, recomendaciones. Soporta Gremlin, openCypher (Property Graph) y SPARQL (RDF)."}, {"name": "Amazon RDS", "category": "Bases de Datos", "tagline": "Relational Database Service", "concept": "Servicio de bases de datos relacionales totalmente administrado. Automatiza tareas como backups, parches, escalado y failover. Soporta 6 motores de bases de datos.", "tip": "RDS = BD SQL administrada. Multi-AZ = alta disponibilidad, failover automático (NO escala lecturas). Read Replicas = escalar lecturas (NO sirve para HA). Sin acceso al SO. Para escalar escrituras horizontalmente → DynamoDB."}, {"name": "AWS CLI", "category": "Herramientas para Desarrolladores", "tagline": "Interfaz de línea de comandos", "concept": "Herramienta unificada para gestionar todos los servicios AWS desde la línea de comandos. Permite automatizar, scripting y gestión de recursos sin usar la consola web.", "tip": "CLI = alternativa a la consola web para gestionar AWS. Necesita credenciales configuradas (access key + secret). Útil para automatización y scripts."}, {"name": "AWS CodeBuild", "category": "Herramientas para Desarrolladores", "tagline": "Compilación y pruebas de código", "concept": "Servicio de integración continua totalmente administrado que compila código fuente, ejecuta pruebas y produce artefactos de software listos para desplegar. Serverless, escala automáticamente.", "tip": "CodeBuild = la fase \"Build\" en CI/CD. CodePipeline orquesta el pipeline completo, CodeBuild realiza la compilación/testing."}, {"name": "AWS CodePipeline", "category": "Herramientas para Desarrolladores", "tagline": "Orquestador de CI/CD", "concept": "Servicio de entrega continua totalmente administrado. Automatiza las fases de release: fuente → compilación → prueba → despliegue. Orquesta herramientas de terceros y de AWS.", "tip": "CodePipeline = el \"director\" del CI/CD. Coordina Source→Build→Test→Deploy. Equivalente a Jenkins orquestado, pero administrado por AWS."}, {"name": "AWS X-Ray", "category": "Herramientas para Desarrolladores", "tagline": "Trazado distribuido y debugging", "concept": "Servicio de trazado distribuido que ayuda a analizar y depurar aplicaciones en producción, especialmente microservicios. Proporciona un mapa visual del flujo de solicitudes y detecta cuellos de botella.", "tip": "X-Ray = tracing distribuido. Para ver exactamente dónde se pierde el tiempo en una request que toca múltiples servicios. Service Map visual."}, {"name": "Amazon AppStream 2.0", "category": "Computación para Usuarios Finales", "tagline": "Streaming de aplicaciones de escritorio", "concept": "Servicio de streaming de aplicaciones de escritorio totalmente administrado. Permite entregar aplicaciones Windows a cualquier dispositivo sin necesidad de instalarlas. Las apps corren en AWS y se transmiten al navegador.", "tip": "AppStream 2.0 = streaming de APLICACIONES (no escritorio completo). Para WorkSpaces es un escritorio virtual completo. AppStream para apps específicas."}, {"name": "Amazon WorkSpaces", "category": "Computación para Usuarios Finales", "tagline": "Escritorios virtuales en la nube (DaaS)", "concept": "Servicio de escritorio como servicio (DaaS) totalmente administrado. Proporciona escritorios Windows o Linux persistentes en la nube, accesibles desde cualquier dispositivo.", "tip": "WorkSpaces = escritorio Windows/Linux completo en la nube. DaaS. Diferente de AppStream (apps individuales) y WorkSpaces Web (navegador seguro)."}, {"name": "Amazon WorkSpaces Secure Browser", "category": "Computación para Usuarios Finales", "tagline": "Navegador web seguro y aislado", "concept": "Navegador web administrado que permite a los empleados acceder a aplicaciones internas y externas de forma segura desde dispositivos no gestionados, sin instalar software.", "tip": "WorkSpaces Secure Browser = acceso web aislado. El navegador corre en AWS, no en el dispositivo del usuario. Datos nunca llegan al endpoint."}, {"name": "AWS Amplify", "category": "Frontend Web y Móvil", "tagline": "Plataforma full-stack para apps web y móvil", "concept": "Conjunto de herramientas y servicios para construir aplicaciones web y móviles full-stack. Incluye autenticación, API GraphQL/REST, almacenamiento, hosting y CI/CD integrado.", "tip": "Amplify = plataforma full-stack para apps móviles/web. Similar a Firebase de Google. Integra múltiples servicios AWS de forma simplificada para desarrolladores frontend."}, {"name": "AWS AppSync", "category": "Frontend Web y Móvil", "tagline": "GraphQL administrado en tiempo real", "concept": "Servicio de API GraphQL totalmente administrado que simplifica el desarrollo de aplicaciones con datos en tiempo real. Conecta aplicaciones con múltiples fuentes de datos (DynamoDB, Lambda, HTTP, RDS).", "tip": "AppSync = API GraphQL administrada con tiempo real. Cuando el examen menciona \"datos en tiempo real en apps móviles\" o \"GraphQL en AWS\" → AppSync."}, {"name": "AWS IoT Core", "category": "Internet de las Cosas (IoT)", "tagline": "Plataforma IoT administrada", "concept": "Servicio administrado para conectar dispositivos IoT a la nube de forma segura. Permite a los dispositivos comunicarse con aplicaciones en la nube y entre sí. Escala a miles de millones de dispositivos y mensajes.", "tip": "IoT Core = conectar dispositivos físicos a AWS. Maneja la comunicación MQTT masiva. Device Shadow sincroniza estado aunque el dispositivo esté offline."}, {"name": "Amazon Comprehend", "category": "Machine Learning / IA", "tagline": "NLP — Análisis de texto", "concept": "Servicio de NLP (Procesamiento de Lenguaje Natural) que extrae información y relaciones del texto. Detecta sentimiento, entidades, frases clave, idioma y PII.", "tip": "Comprehend = NLP sin código. Analizar texto → Comprehend. Detectar PII en documentos → Comprehend. Sin necesidad de ML expertise."}, {"name": "Amazon Kendra", "category": "Machine Learning / IA", "tagline": "Búsqueda empresarial inteligente con ML", "concept": "Servicio de búsqueda empresarial impulsado por ML. Devuelve respuestas precisas de documentos, no solo listas de links. Entiende preguntas en lenguaje natural.", "tip": "Kendra = búsqueda empresarial con ML. Entiende preguntas (\"¿Cuáles son los beneficios de salud?\") y responde del contenido de documentos internos."}, {"name": "Amazon Lex", "category": "Machine Learning / IA", "tagline": "Chatbots y asistentes de voz con IA", "concept": "Servicio para crear interfaces de conversación (chatbots) con voz y texto. Usa la misma tecnología que Alexa. Soporta reconocimiento de voz (ASR) y NLU.", "tip": "Lex = tecnología detrás de Alexa para crear tus propios bots. Integra con Lambda para lógica de negocio y Connect para call centers."}, {"name": "Amazon Polly", "category": "Machine Learning / IA", "tagline": "Text-to-Speech (TTS)", "concept": "Servicio que convierte texto en voz realista (TTS). Soporta docenas de idiomas y voces, incluyendo voces neurales de alta calidad. Genera audio MP3/OGG.", "tip": "Polly = texto → voz. Lo opuesto de Transcribe (voz → texto). Voces neurales muy naturales. Incluye español latinoamericano."}, {"name": "Amazon Q", "category": "Machine Learning / IA", "tagline": "Asistente de IA empresarial generativo", "concept": "Asistente de IA generativa para empresas y desarrolladores. Amazon Q Business responde preguntas sobre datos internos; Amazon Q Developer ayuda con código en IDEs. Powered by LLMs de Amazon.", "tip": "Amazon Q = asistente IA generativo de AWS. Q Business para preguntas sobre datos internos empresariales. Q Developer = copiloto de código en IDE (similar a GitHub Copilot)."}, {"name": "Amazon Rekognition", "category": "Machine Learning / IA", "tagline": "Análisis de imágenes y video con IA", "concept": "Servicio de visión computacional que analiza imágenes y videos. Detecta objetos, escenas, texto, rostros, actividades inapropiadas y más, sin necesidad de ML expertise.", "tip": "Rekognition = análisis de imágenes y video. Sin escribir código de ML. Reconocimiento facial, objetos, texto en imágenes, moderación de contenido."}, {"name": "Amazon SageMaker AI", "category": "Machine Learning / IA", "tagline": "Plataforma ML end-to-end", "concept": "Plataforma ML totalmente administrada para construir, entrenar y desplegar modelos de ML a escala. Cubre todo el ciclo de vida: preparación de datos, entrenamiento, evaluación, despliegue e inferencia.", "tip": "SageMaker = si necesitas CONSTRUIR tu propio modelo ML. Diferente de Rekognition/Comprehend/Polly (servicios de IA listos para usar sin entrenamiento)."}, {"name": "Amazon Textract", "category": "Machine Learning / IA", "tagline": "Extracción de texto de documentos (OCR)", "concept": "Servicio de ML que extrae automáticamente texto, datos de formularios y tablas de documentos escaneados (imágenes, PDFs). Va más allá del OCR tradicional entendiendo la estructura del documento.", "tip": "Textract = OCR avanzado con comprensión de estructura. Extrae tablas y formularios, no solo texto plano. Para procesar documentos escaneados en masa."}, {"name": "Amazon Transcribe", "category": "Machine Learning / IA", "tagline": "Speech-to-Text (STT)", "concept": "Servicio de reconocimiento automático de voz (ASR) que convierte audio en texto. Soporta múltiples idiomas, identificación de hablantes, redacción de PII y vocabularios personalizados.", "tip": "Transcribe = voz → texto. Lo opuesto de Polly (texto → voz). Medical Transcribe para terminología médica. Transcribe Call Analytics para call centers."}, {"name": "Amazon Translate", "category": "Machine Learning / IA", "tagline": "Traducción automática neural", "concept": "Servicio de traducción automática neuronal rápida, asequible y de alta calidad. Soporta más de 75 idiomas. Permite localizar contenido a gran escala.", "tip": "Translate = traducción automática de AWS. Integra con Comprehend para análisis multilingüe. Para localización masiva de contenido sin traductores humanos."}, {"name": "AWS Auto Scaling", "category": "Administración y Gobernanza", "tagline": "Escalado automático de recursos", "concept": "Monitorea aplicaciones y ajusta automáticamente la capacidad para mantener rendimiento constante al menor costo. Escala EC2, ECS, DynamoDB, Aurora y más.", "tip": "Auto Scaling = elasticidad automática. EC2 Auto Scaling Groups para instancias. Target Tracking más simple: \"mantén CPU al 50%\". Clave para alta disponibilidad y costo-eficiencia."}, {"name": "AWS CloudFormation", "category": "Administración y Gobernanza", "tagline": "Infraestructura como Código (IaC)", "concept": "Servicio de infraestructura como código (IaC). Define y provisiona toda tu infraestructura AWS en archivos de texto (YAML/JSON). Permite repetir despliegues de forma consistente.", "tip": "CloudFormation = IaC de AWS. YAML/JSON para definir toda la infra. StackSets para desplegar en múltiples cuentas/regiones. CDK es código (Python/JS) que genera CloudFormation."}, {"name": "AWS CloudTrail", "category": "Administración y Gobernanza", "tagline": "Auditoría de llamadas a la API de AWS", "concept": "Servicio que registra todas las llamadas a la API de AWS (quién hizo qué, cuándo y desde dónde). Proporciona historial de eventos para gobernanza, cumplimiento y auditoría operacional y de seguridad.", "tip": "CloudTrail = \"cámara de seguridad\" de la API de AWS. Habilitado por defecto 90 días. Para retención mayor → crear un Trail en S3. CloudTrail ≠ CloudWatch (métricas vs logs de API)."}, {"name": "Amazon CloudWatch", "category": "Administración y Gobernanza", "tagline": "Monitoreo y observabilidad", "concept": "Servicio de monitoreo y observabilidad para AWS. Recopila y rastrea métricas, archivos de registro y eventos. Permite configurar alarmas, dashboards y respuestas automáticas.", "tip": "CloudWatch = monitoreo de recursos y aplicaciones. Métricas cada 5 min (gratis) o 1 min (detallado). Alarmas pueden disparar acciones. CloudTrail = quién hizo qué. CloudWatch = cómo está funcionando."}, {"name": "AWS Compute Optimizer", "category": "Administración y Gobernanza", "tagline": "Recomendaciones de optimización de recursos", "concept": "Analiza métricas de uso y recomienda recursos AWS óptimos para reducir costos y mejorar rendimiento. Usa ML para analizar historial de CloudWatch.", "tip": "Compute Optimizer = recomendaciones de right-sizing. \"Estás pagando por m5.xlarge pero usas el 5% de CPU\" → recomienda m5.small. Reduce costos sin perder rendimiento."}, {"name": "AWS Config", "category": "Administración y Gobernanza", "tagline": "Auditoría de configuración de recursos", "concept": "Servicio que registra continuamente las configuraciones de recursos AWS y evalúa cambios contra reglas de cumplimiento. Responde: \"¿Cómo estaba configurado X en una fecha específica?\"", "tip": "Config = inventario y cumplimiento de configuraciones. CloudTrail = quién hizo el cambio. Config = qué cambió y si cumple las reglas. Config Rules para validar compliance."}, {"name": "AWS Control Tower", "category": "Administración y Gobernanza", "tagline": "Gobernanza multi-cuenta automatizada", "concept": "Servicio para configurar y gobernar un entorno multi-cuenta seguro y cumplidor (landing zone) de forma automatizada. Aplica guardrails (controles) preventivos y detectivos en todas las cuentas.", "tip": "Control Tower = gobierno automatizado de múltiples cuentas AWS. Construido sobre Organizations. Para empresas que crean muchas cuentas y necesitan políticas consistentes."}, {"name": "AWS Health Dashboard", "category": "Administración y Gobernanza", "tagline": "Estado y salud de servicios AWS", "concept": "Proporciona información personalizada sobre el estado de los servicios AWS que afectan tu cuenta específica. Incluye Service Health (estado global) y Account Health (alertas personalizadas para tu cuenta).", "tip": "Health Dashboard = estado de AWS para TU cuenta. Service Health = estado global público. Account Health = alertas personalizadas relevantes para tus recursos."}, {"name": "AWS License Manager", "category": "Administración y Gobernanza", "tagline": "Gestión de licencias de software", "concept": "Simplifica la gestión de licencias de software en AWS y on-premises. Controla el uso de licencias de Microsoft, Oracle, SAP, IBM y otros para evitar sobre-uso y penalizaciones.", "tip": "License Manager = seguimiento de licencias de software. Evita violaciones de licencias al rastrear el uso en instancias EC2. Integra con Systems Manager."}, {"name": "Consola de Administración AWS", "category": "Administración y Gobernanza", "tagline": "Interfaz web de gestión de AWS", "concept": "Interfaz web (GUI) para gestionar todos los servicios AWS. Permite crear, configurar y monitorear recursos sin usar la línea de comandos. Accesible desde cualquier navegador web.", "tip": "La consola es la GUI de AWS. Alternativas: CLI (línea de comandos), SDKs (código), CloudFormation (IaC). La consola no sirve para automatización a escala."}, {"name": "AWS Organizations", "category": "Administración y Gobernanza", "tagline": "Gestión centralizada de múltiples cuentas", "concept": "Servicio para gestionar y gobernar múltiples cuentas AWS de forma centralizada. Permite agrupar cuentas en unidades organizativas (OUs), aplicar Service Control Policies (SCPs) y facturación consolidada.", "tip": "Organizations = gestión multi-cuenta. SCP = límites de lo que los usuarios PUEDEN hacer (incluso administradores). Facturación consolidada = una factura para todas las cuentas + descuentos."}, {"name": "AWS Service Catalog", "category": "Administración y Gobernanza", "tagline": "Catálogo de productos aprobados por TI", "concept": "Permite a las organizaciones crear y gestionar catálogos de servicios de TI aprobados para usar en AWS. Los usuarios pueden desplegar solo los recursos pre-aprobados, manteniendo compliance.", "tip": "Service Catalog = menú aprobado de recursos AWS. TI define qué puede desplegar cada equipo. Gobernanza + self-service. Basado en CloudFormation templates."}, {"name": "Service Quotas", "category": "Administración y Gobernanza", "tagline": "Gestión de límites de servicios AWS", "concept": "Vista centralizada de todas las cuotas (límites) de servicios AWS en tu cuenta. Permite solicitar aumentos de cuota y configurar alarmas de CloudWatch cuando se acerquen los límites.", "tip": "Service Quotas = ver y solicitar aumentar límites de AWS (ej: número máximo de VPCs, instancias EC2). Antes se llamaba \"Límites de servicio\" y se gestionaba por Support."}, {"name": "AWS Systems Manager", "category": "Administración y Gobernanza", "tagline": "Gestión operacional de recursos", "concept": "Plataforma de gestión operacional unificada para infraestructura en AWS y on-premises. Ofrece visibilidad y control de la infraestructura sin necesidad de SSH/RDP directo.", "tip": "Systems Manager = herramienta operacional multi-propósito. Session Manager reemplaza SSH/bastion hosts. Parameter Store para configs (Secrets Manager para secretos críticos)."}, {"name": "AWS Trusted Advisor", "category": "Administración y Gobernanza", "tagline": "Recomendaciones de mejores prácticas", "concept": "Herramienta online que analiza el entorno AWS y proporciona recomendaciones en tiempo real basadas en mejores prácticas de AWS. Analiza 5 categorías principales.", "tip": "Trusted Advisor = consultor automático de AWS. 5 pilares: costo, rendimiento, seguridad, tolerancia a fallos, límites. Business+ plan para todos los checks."}, {"name": "AWS Well-Architected Tool", "category": "Administración y Gobernanza", "tagline": "Revisión de arquitecturas cloud", "concept": "Herramienta gratuita que ayuda a revisar arquitecturas cloud usando el AWS Well-Architected Framework. Identifica riesgos y brinda orientación para construir infraestructuras seguras, eficientes y rentables.", "tip": "Well-Architected Framework = 6 pilares. La herramienta aplica cuestionarios para evaluar tu arquitectura contra esos pilares. MUY importante para el examen. Memoriza los 6 pilares."}, {"name": "AWS Application Discovery Service", "category": "Migración y Transferencia", "tagline": "Descubrimiento de infraestructura on-premises", "concept": "Ayuda a planificar migraciones recopilando información sobre servidores on-premises: configuración, uso, dependencias. Dos modos: agentless (VMware) y agent-based.", "tip": "Application Discovery = primer paso de migración: descubrir qué tienes. Integra con Migration Hub para rastrear el progreso de migración."}, {"name": "AWS Application Migration Service", "category": "Migración y Transferencia", "tagline": "Migración lift-and-shift de servidores", "concept": "Simplifica y agiliza las migraciones lift-and-shift (rehost). Replica servidores físicos, virtuales o en la nube a AWS de forma continua, con mínimo tiempo de inactividad.", "tip": "App Migration Service (MGN) = lift-and-shift automático. Antes llamado Server Migration Service. Mínimo downtime durante migración. Para VMs completas."}, {"name": "AWS DMS", "category": "Migración y Transferencia", "tagline": "Database Migration Service", "concept": "Migra bases de datos a AWS de forma rápida y segura. Soporta migraciones homogéneas (MySQL→RDS MySQL) y heterogéneas (Oracle→Aurora). Mantiene la BD fuente operativa durante la migración.", "tip": "DMS = migrar bases de datos con mínimo downtime. Para heterogéneas (ej: Oracle→Aurora) usar SCT primero para convertir el esquema. DMS + SCT = combo de migración de BD."}, {"name": "Migration Evaluator", "category": "Migración y Transferencia", "tagline": "Análisis económico de migración", "concept": "Proporciona análisis económico basado en datos reales de infraestructura on-premises para construir el caso de negocio para migrar a AWS. Calcula TCO y potencial ahorro.", "tip": "Migration Evaluator = business case para migrar. Recopila datos de uso real y muestra cuánto ahorrarías en AWS. Para convencer a dirección de migrar."}, {"name": "AWS Migration Hub", "category": "Migración y Transferencia", "tagline": "Centro de seguimiento de migraciones", "concept": "Ubicación central para rastrear el progreso de migraciones de aplicaciones a través de múltiples herramientas de migración de AWS y partners. Dashboard unificado de estado de migración.", "tip": "Migration Hub = panel de control central de migraciones. Agrega datos de DMS, MGN, Application Discovery. Ver todo el progreso en un solo lugar."}, {"name": "AWS Schema Conversion Tool (SCT)", "category": "Migración y Transferencia", "tagline": "Conversión de esquemas de BD heterogéneas", "concept": "Herramienta de escritorio (gratuita) que convierte automáticamente el esquema de una BD fuente a un formato compatible con la BD destino. Convierte tablas, vistas, procedimientos almacenados.", "tip": "SCT = convertir esquemas antes de migrar. Oracle → Aurora: SCT convierte el esquema, DMS migra los datos. SCT es tool de escritorio descargable, no servicio cloud."}, {"name": "AWS Snow Family", "category": "Migración y Transferencia", "tagline": "Transferencia física de datos a AWS", "concept": "Dispositivos físicos para mover grandes volúmenes de datos hacia/desde AWS cuando internet sería muy lento o costoso. También tienen capacidad de cómputo para edge computing.", "tip": "Snow Family = transferencia FÍSICA de datos. Regla práctica: si mover datos por internet tarda > 1 semana → usa Snowball. Snowmobile para exabytes (datacenter completo)."}, {"name": "Amazon API Gateway", "category": "Redes y Entrega de Contenido", "tagline": "Gestión de APIs REST/HTTP/WebSocket", "concept": "Servicio totalmente administrado para crear, publicar, mantener, monitorear y proteger APIs a cualquier escala. Actúa como \"puerta de entrada\" para acceder a backend (Lambda, EC2, HTTP).", "tip": "API Gateway = front-door de APIs. Lambda + API Gateway = arquitectura serverless típica. HTTP API más barata y simple que REST API. WebSocket para apps en tiempo real."}, {"name": "Amazon CloudFront", "category": "Redes y Entrega de Contenido", "tagline": "CDN global — Content Delivery Network", "concept": "Red de entrega de contenido (CDN) global. Distribuye contenido (estático, dinámico, streaming, APIs) con baja latencia desde 410+ puntos de presencia (PoPs) alrededor del mundo.", "tip": "CloudFront = CDN de AWS. Reduce latencia sirviendo desde el edge más cercano. S3 + CloudFront = hosting web estático global. OAC restringe S3 a solo CloudFront."}, {"name": "AWS Direct Connect", "category": "Redes y Entrega de Contenido", "tagline": "Conexión privada dedicada a AWS", "concept": "Conexión de red dedicada y privada entre instalaciones on-premises y AWS, pasando por un proveedor de conectividad. Proporciona ancho de banda consistente y latencia reducida vs internet.", "tip": "Direct Connect = conexión privada FÍSICA a AWS. Más caro que VPN pero más estable, rápido y consistente. NO pasa por internet. Tarda semanas en configurar."}, {"name": "AWS Global Accelerator", "category": "Redes y Entrega de Contenido", "tagline": "Mejora rendimiento de apps globales", "concept": "Servicio de red que mejora la disponibilidad y rendimiento de aplicaciones globales usando la red global de AWS. Dirige el tráfico al endpoint óptimo mediante 2 IPs anycast estáticas.", "tip": "Global Accelerator ≠ CloudFront. GA para apps TCP/UDP que necesitan IPs fijas globales. CloudFront para contenido HTTP cacheable. Ambos usan la red de AWS, no internet."}, {"name": "AWS PrivateLink", "category": "Redes y Entrega de Contenido", "tagline": "Acceso privado a servicios AWS/SaaS", "concept": "Proporciona conectividad privada entre VPCs, servicios AWS y aplicaciones on-premises sin exponer el tráfico a internet público. Usa endpoints de interfaz (ENIs con IP privada).", "tip": "PrivateLink = tráfico NUNCA sale a internet. VPC Endpoints usan PrivateLink. Gateway Endpoints para S3/DynamoDB (gratis). Interface Endpoints para otros servicios (con costo)."}, {"name": "Amazon Route 53", "category": "Redes y Entrega de Contenido", "tagline": "DNS administrado y registro de dominios", "concept": "Servicio DNS web altamente disponible y escalable. También registra nombres de dominio. Nombre \"53\" por el puerto DNS. Soporta múltiples políticas de enrutamiento.", "tip": "Route 53 = DNS de AWS. Weighted routing para A/B testing. Latency routing para mejor rendimiento global. Failover routing para alta disponibilidad. Geolocation para restricciones geográficas."}, {"name": "AWS Transit Gateway", "category": "Redes y Entrega de Contenido", "tagline": "Hub de conectividad de red central", "concept": "Actúa como hub central para conectar VPCs, cuentas AWS y redes on-premises. Simplifica la arquitectura de red eliminando el modelo hub-and-spoke complejo de VPC peering.", "tip": "Transit Gateway = router central para múltiples VPCs. Sin TGW necesitarías N*(N-1)/2 peering connections. Con TGW, cada VPC se conecta solo al hub. Escala mejor."}, {"name": "Amazon VPC", "category": "Redes y Entrega de Contenido", "tagline": "Virtual Private Cloud — Red privada en AWS", "concept": "Sección lógicamente aislada de la nube AWS donde puedes lanzar recursos en una red virtual que defines. Control completo sobre el entorno de red: rangos IP, subredes, tablas de rutas, gateways.", "tip": "VPC es el bloque fundamental de red en AWS. SG = stateful (recuerda conexiones), NACL = stateless (evalúa cada paquete). Default VPC existe en cada cuenta/región."}, {"name": "AWS VPN", "category": "Redes y Entrega de Contenido", "tagline": "Site-to-Site VPN y Client VPN", "concept": "Conexión cifrada entre red on-premises y VPC de AWS sobre internet público. Solución rápida de configurar (vs semanas de Direct Connect). Dos tipos principales.", "tip": "VPN = conexión cifrada sobre internet (rápido de configurar, más barato). Direct Connect = conexión privada dedicada (más lento de configurar, más costoso, más estable)."}, {"name": "AWS Artifact", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Informes de cumplimiento y acuerdos", "concept": "Portal de autoservicio para descargar informes de auditoría y seguridad de AWS, y gestionar acuerdos (BAA, NDA). Proporciona acceso bajo demanda a documentación de cumplimiento de AWS.", "tip": "Artifact = repositorio de documentos de compliance de AWS. Para mostrar a auditores que AWS cumple ISO 27001, SOC 2, PCI-DSS, HIPAA, etc. Totalmente gratuito."}, {"name": "AWS Audit Manager", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Auditoría continua y automática", "concept": "Automatiza la recopilación de evidencia para auditorías. Mapea controles de cumplimiento (PCI-DSS, HIPAA, GDPR) a actividades de AWS y genera informes de auditoría automáticamente.", "tip": "Audit Manager = automatizar preparación de auditorías. Recopila evidencia automáticamente de CloudTrail, Config, Security Hub. Reduce trabajo manual de auditores."}, {"name": "AWS Certificate Manager (ACM)", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Certificados SSL/TLS gestionados", "concept": "Provisiona, gestiona y despliega certificados SSL/TLS para su uso con servicios AWS. Los certificados públicos son GRATUITOS. Renueva automáticamente los certificados.", "tip": "ACM = certificados SSL gratuitos y auto-renovados. Solo para servicios AWS (no para servidores EC2 directamente). CloudFront + ACM = HTTPS global gratuito."}, {"name": "AWS CloudHSM", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Hardware Security Module dedicado", "concept": "Hardware Security Module (HSM) en la nube. Genera y usa claves criptográficas en hardware dedicado y validado (FIPS 140-2 Nivel 3). Solo el cliente controla las claves.", "tip": "CloudHSM = cuando necesitas HSM dedicado (no compartido) y FIPS 140-2 Level 3. Más caro y complejo que KMS. Regulaciones muy estrictas (defensa, bancos centrales)."}, {"name": "Amazon Cognito", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Autenticación para aplicaciones web y móvil", "concept": "Servicio de autenticación, autorización y gestión de usuarios para apps web y móviles. Soporta registro/login de usuarios, federación de identidades (Google, Facebook, SAML) y tokens JWT.", "tip": "Cognito = auth para TUS aplicaciones (no para acceder a la consola AWS). User Pools = login de usuarios. Identity Pools = obtener credenciales AWS para usuarios. Federa con Google/Facebook/SAML."}, {"name": "Amazon Detective", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Investigación de incidentes de seguridad", "concept": "Servicio que facilita analizar, investigar e identificar la causa raíz de hallazgos de seguridad. Recopila automáticamente datos de log y usa ML para crear visualizaciones interactivas.", "tip": "Detective = investigar incidentes de seguridad (post-evento). GuardDuty = detectar amenazas (en tiempo real). Security Hub = agregar hallazgos. Detective = análisis forense."}, {"name": "AWS Directory Service", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Microsoft AD administrado en AWS", "concept": "Proporciona opciones de Microsoft Active Directory en AWS. Permite conectar recursos AWS a un AD on-premises existente o crear un nuevo AD administrado en la nube.", "tip": "Directory Service = Active Directory en AWS. AD Connector para conectar AD on-prem con AWS. Managed AD para AD completo en AWS. Necesario para WorkSpaces con AD."}, {"name": "AWS Firewall Manager", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Gestión centralizada de reglas de firewall", "concept": "Administra y aplica centralmente reglas de firewall en toda una organización AWS Organizations. Gestiona WAF, Shield Advanced, Security Groups y Network Firewall de forma centralizada.", "tip": "Firewall Manager = aplicar reglas WAF/Shield/SG en múltiples cuentas de Organizations automáticamente. Asegura que todas las cuentas sigan la misma política de seguridad."}, {"name": "Amazon GuardDuty", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Detección inteligente de amenazas", "concept": "Servicio de detección de amenazas continuo que monitorea actividad maliciosa y comportamiento no autorizado usando ML, anomalías y threat intelligence. Analiza CloudTrail, DNS logs y VPC Flow Logs.", "tip": "GuardDuty = IDS/IPS en la nube. Sin instalar agentes. Habilitar con un click. Los hallazgos van a Security Hub. Regiones independientes: habilitar en cada región. 30 días gratis."}, {"name": "AWS IAM", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Identity and Access Management", "concept": "Servicio web para controlar el acceso a recursos AWS. Administra quién puede autenticarse (identidad) y qué acciones están autorizados a realizar (control de acceso).", "tip": "IAM = pilar de seguridad de AWS. Global (no por región). Grupos para permisos de usuarios. Roles para servicios. Policies = JSON de permisos. MFA obligatorio para root. Least privilege siempre."}, {"name": "AWS IAM Identity Center", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "SSO para múltiples cuentas AWS", "concept": "Servicio de Single Sign-On (SSO) que permite gestionar el acceso de la fuerza laboral a múltiples cuentas AWS y aplicaciones empresariales desde un lugar central. Antes llamado AWS SSO.", "tip": "IAM Identity Center = SSO para cuentas AWS múltiples con Organizations. Un login para acceder a todas las cuentas. Antes: AWS SSO. Para workforce (empleados), no para usuarios de apps."}, {"name": "Amazon Inspector", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Análisis de vulnerabilidades automático", "concept": "Servicio de gestión de vulnerabilidades que escanea automáticamente cargas de trabajo AWS (instancias EC2, contenedores, Lambda) en busca de vulnerabilidades de software y exposición de red no intencionada.", "tip": "Inspector = escaneo de vulnerabilidades (CVEs) en EC2, contenedores y Lambda. Automático y continuo. Integra con Security Hub. Similar a \"Nessus\" pero administrado en AWS."}, {"name": "AWS KMS", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Key Management Service", "concept": "Servicio administrado para crear y controlar claves criptográficas para encriptar datos. Integrado con casi todos los servicios AWS. Usa HSMs validados para proteger las claves. FIPS 140-2 L2.", "tip": "KMS = gestión de claves de encriptación. La mayoría de servicios AWS usan KMS para encriptación en reposo. Customer Managed Keys = más control y auditoría. KMS ≠ CloudHSM (HSM dedicado)."}, {"name": "Amazon Macie", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Descubrimiento de datos sensibles en S3", "concept": "Servicio de seguridad de datos con ML que descubre, clasifica y protege automáticamente datos sensibles en Amazon S3. Identifica PII (nombres, SSN, tarjetas de crédito, credenciales).", "tip": "Macie = encontrar datos sensibles (PII) en S3 con ML. \"¿Tenemos datos personales expuestos en S3?\" → Macie. Genera hallazgos en Security Hub."}, {"name": "AWS Resource Access Manager (RAM)", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Compartir recursos entre cuentas AWS", "concept": "Permite compartir recursos AWS entre cuentas dentro de AWS Organizations o cuentas externas. Evita duplicar recursos en cada cuenta.", "tip": "RAM = compartir recursos entre cuentas sin copiarlos. Caso típico: compartir una subred VPC o Transit Gateway entre múltiples cuentas de una organización."}, {"name": "AWS Secrets Manager", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Gestión de secretos y credenciales", "concept": "Servicio para almacenar, rotar, gestionar y recuperar credenciales de bases de datos, claves API y otros secretos. Rotación automática integrada con RDS, Redshift y DocumentDB.", "tip": "Secrets Manager = almacenar contraseñas/API keys con rotación automática. Cuando pregunten \"cómo almacenar credenciales de DB de forma segura con rotación\" → Secrets Manager."}, {"name": "AWS Security Hub", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Centro de seguridad unificado", "concept": "Agrega, organiza y prioriza alertas de seguridad (hallazgos) de múltiples servicios AWS y herramientas de terceros en una vista unificada. Verifica automáticamente el cumplimiento de estándares.", "tip": "Security Hub = SIEM de AWS / panel único de seguridad. Agrega hallazgos de todos los servicios de seguridad. Evalúa contra CIS Benchmarks, PCI-DSS, etc."}, {"name": "AWS Shield", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Protección contra ataques DDoS", "concept": "Servicio administrado de protección contra DDoS (Distributed Denial of Service). Disponible en dos niveles: Standard (automático, gratuito) y Advanced (protección premium, $3,000/mes).", "tip": "Shield Standard = gratis y automático para TODOS. Shield Advanced = protección avanzada, DRT (Equipo de Respuesta DDoS), reembolso de costos por DDoS. WAF incluido en Advanced."}, {"name": "AWS WAF", "category": "Seguridad, Identidad y Cumplimiento", "tagline": "Web Application Firewall", "concept": "Firewall de aplicaciones web que protege contra exploits web comunes (inyección SQL, XSS, etc.) que pueden afectar disponibilidad, comprometer seguridad o consumir recursos excesivos.", "tip": "WAF = firewall de capa 7 (HTTP). Shield = protección DDoS capa 3/4. WAF filtra requests maliciosas. Se define mediante ACLs con reglas. WAF + Shield + CloudFront = protección completa."}, {"name": "AWS Fargate", "category": "Sin Servidor (Serverless)", "tagline": "Cómputo serverless para contenedores", "concept": "Motor de cómputo serverless para contenedores que funciona con Amazon ECS y EKS. Elimina la necesidad de gestionar servidores o clústeres. Solo pagas por los recursos que consumen tus contenedores.", "tip": "Fargate = serverless para contenedores. No gestionas EC2. Lambda = serverless para código (funciones). Fargate = serverless para contenedores. Ambos son serverless pero diferentes."}, {"name": "AWS Lambda", "category": "Sin Servidor (Serverless)", "tagline": "Cómputo serverless orientado a eventos", "concept": "Servicio de cómputo serverless que ejecuta código en respuesta a eventos sin aprovisionar ni gestionar servidores. Se escala automáticamente y cobras solo por el tiempo de ejecución.", "tip": "Lambda = FaaS. Sin servidores. Máximo 15 minutos. Free tier muy generoso. Para tareas cortas y reactivas. Lambda + API Gateway + DynamoDB = arquitectura serverless canónica de AWS."}, {"name": "AWS Backup", "category": "Almacenamiento", "tagline": "Centraliza y automatiza backups", "concept": "Servicio administrado centralizado para automatizar y gestionar backups en servicios AWS. Política de backup única para EC2, EBS, EFS, RDS, DynamoDB, S3, FSx, etc.", "tip": "AWS Backup = un lugar para gestionar todos los backups. Reemplaza configurar backups servicio por servicio. Planes de backup con retención y frecuencia centralizados."}, {"name": "Amazon EBS", "category": "Almacenamiento", "tagline": "Elastic Block Store — Disco para EC2", "concept": "Almacenamiento en bloque de alta performance para instancias EC2. Los volúmenes EBS persisten independientemente de la instancia. Se puede adjuntar/desadjuntar de instancias.", "tip": "EBS = disco duro virtual para EC2. Persiste sin la instancia. Ligado a UNA AZ. Para adjuntar a múltiples instancias: EFS. Multi-Attach solo para io2. Snapshots son cross-region."}, {"name": "Amazon EFS", "category": "Almacenamiento", "tagline": "Elastic File System — NFS administrado", "concept": "Sistema de archivos NFS totalmente administrado y elástico para cargas de trabajo en Linux. Se puede montar en miles de instancias EC2 simultáneamente. Escala automáticamente sin provisionar.", "tip": "EFS = NFS compartido multi-instancia, multi-AZ. Solo Linux (POSIX). Si necesitas compartir archivos entre instancias EC2 → EFS. Para Windows SMB → FSx for Windows."}, {"name": "Elastic Disaster Recovery", "category": "Almacenamiento", "tagline": "Recuperación ante desastres rápida", "concept": "Minimiza el tiempo de inactividad y pérdida de datos con recuperación ante desastres rápida y confiable en AWS para servidores físicos, virtuales y en otras nubes. Replicación continua de bajo costo.", "tip": "Elastic DR = DR de bajo RPO/RTO para servidores. Antes llamado CloudEndure DR. Replica continuamente. En caso de desastre, lanza instancias EC2 en minutos."}, {"name": "Amazon FSx", "category": "Almacenamiento", "tagline": "Sistemas de archivos de terceros administrados", "concept": "Servicio que ofrece sistemas de archivos de terceros de alta performance totalmente administrados en AWS. Elimina la gestión administrativa de sistemas de archivos complejos.", "tip": "FSx for Windows = EFS para Windows (SMB, AD integración). FSx for Lustre = high performance computing, integra con S3. Memoriza: Windows=Windows File Share, Lustre=HPC."}, {"name": "Amazon S3", "category": "Almacenamiento", "tagline": "Simple Storage Service — Almacenamiento de objetos", "concept": "Servicio de almacenamiento de objetos con escalabilidad, disponibilidad, seguridad y rendimiento líderes del sector. Almacena y recupera cualquier cantidad de datos desde cualquier lugar. Durabilidad 11 nueves (99.999999999%).", "tip": "S3 = almacenamiento de objetos, durabilidad 11 nines (99.999999999%), bucket names globalmente únicos, máx 5TB/objeto, sin límite de bucket. Lifecycle policies mueven datos entre clases automáticamente para ahorrar."}, {"name": "Amazon S3 Glacier", "category": "Almacenamiento", "tagline": "Archiving de bajo costo a largo plazo", "concept": "Servicio de almacenamiento seguro, duradero y extremadamente barato para archiving de datos y backup a largo plazo. Parte de las clases de almacenamiento S3. El precio es el más bajo posible a cambio de tiempo de recuperación.", "tip": "Glacier = archiving barato. Cuanto más esperas para recuperar, más barato. Deep Archive = lo más barato de todo AWS. Para logs de compliance que nunca se leen pero deben guardarse 7 años."}, {"name": "AWS Storage Gateway", "category": "Almacenamiento", "tagline": "Integración de almacenamiento híbrido", "concept": "Servicio de almacenamiento híbrido que conecta entornos on-premises con almacenamiento en la nube AWS. Proporciona acceso local a almacenamiento cloud con baja latencia mediante caché local.", "tip": "Storage Gateway = puente entre on-premises y AWS storage. Tape Gateway reemplaza cintas físicas (VTL). File Gateway para NFS/SMB hacia S3. Corre como VM on-prem o EC2."}];
(function(){
 const $=id=>document.getElementById(id);
 const categories=[...new Set(STUDY_BANK.map(x=>x.category))].sort();
 categories.forEach(c=>{const o=document.createElement('option');o.value=c;o.textContent=c;$('quizCategory').append(o)});
 const statsKey='aws-academy-exam-history-v1';
 const loadHistory=()=>{try{const h=JSON.parse(localStorage.getItem(statsKey)||'[]');return Array.isArray(h)?h:[]}catch{return []}};
 const saveHistory=h=>{try{localStorage.setItem(statsKey,JSON.stringify(h))}catch{}};
 let questions=[],index=0,answers=[],mode='practice',locked=false;
 const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};
 const uniqueByName=a=>[...new Map(a.map(x=>[x.name,x])).values()];
 function updateStats(){
   const h=loadHistory();$('statAttempts').textContent=h.length;
   $('statAverage').textContent=h.length?Math.round(h.reduce((s,x)=>s+x.percent,0)/h.length)+'%':'—';
   $('statBest').textContent=h.length?Math.max(...h.map(x=>x.percent))+'%':'—';
   $('statAnswered').textContent=h.reduce((s,x)=>s+x.total,0);
 }
 function show(id){['quizSetup','quizPlay','quizResults'].forEach(x=>$(x).hidden=x!==id)}
 function buildQuestions(){
   const selected=$('quizCategory').value;
   const pool=uniqueByName(STUDY_BANK.filter(x=>selected==='all'||x.category===selected));
   const global=uniqueByName(STUDY_BANK);
   return shuffle(pool).slice(0,Math.min(Number($('quizSize').value),pool.length)).map(item=>{
     const inCategory=global.filter(x=>x.category===item.category&&x.name!==item.name);
     const distractors=shuffle(inCategory).slice(0,3);
     if(distractors.length<3)distractors.push(...shuffle(global.filter(x=>x.name!==item.name&&!distractors.some(y=>y.name===x.name))).slice(0,3-distractors.length));
     const options=shuffle([item.name,...distractors.map(x=>x.name)]);
     return {item,options,correct:item.name,chosen:null};
   });
 }
 function renderQuestion(){
   locked=false;const q=questions[index];$('quizStep').textContent=`Pregunta ${index+1} de ${questions.length}`;
   $('quizCurrentScore').textContent=`${answers.filter(a=>a.correct).length} aciertos`;
   $('quizTrackFill').style.width=(index/questions.length*100)+'%';
   $('quizCategoryBadge').textContent=q.item.category;
   $('quizQuestion').textContent='¿Qué servicio de AWS corresponde a esta descripción?';
   const description=document.createElement('p');description.className='quiz-description';description.textContent=q.item.tagline;
   $('quizQuestion').replaceChildren(document.createTextNode('¿Qué servicio de AWS corresponde a esta descripción?'),description);
   $('quizOptions').replaceChildren();$('quizFeedback').hidden=true;$('nextQuiz').disabled=true;
   $('nextQuiz').textContent=index===questions.length-1?'Ver resultados →':'Siguiente →';
   q.options.forEach(option=>{
     const btn=document.createElement('button');btn.type='button';btn.className='quiz-option';btn.textContent=option;
     btn.addEventListener('click',()=>choose(option));$('quizOptions').append(btn);
   });
 }
 function choose(option){
   if(locked)return;locked=true;const q=questions[index];q.chosen=option;
   const correct=option===q.correct;answers.push({correct,question:q.item.tagline,answer:option,expected:q.correct,tip:q.item.tip});
   [...$('quizOptions').children].forEach(b=>{
     b.disabled=true;
     if(mode==='practice'){if(b.textContent===q.correct)b.classList.add('correct');else if(b.textContent===option)b.classList.add('incorrect')}
     else if(b.textContent===option)b.style.borderColor='var(--accent2)';
   });
   if(mode==='practice'){
     $('quizFeedback').hidden=false;
     $('quizFeedback').textContent=(correct?'✓ Correcto. ':'✗ Respuesta correcta: '+q.correct+'. ')+(q.item.tip||q.item.concept);
   }
   $('quizCurrentScore').textContent=`${answers.filter(a=>a.correct).length} aciertos`;
   $('nextQuiz').disabled=false;
 }
 function finish(){
   const right=answers.filter(a=>a.correct).length,total=questions.length,percent=Math.round(right/total*100);
   const h=loadHistory();h.push({date:new Date().toISOString(),right,total,percent});saveHistory(h);updateStats();
   $('quizResultScore').textContent=percent+'%';
   $('quizResultTitle').textContent=percent>=80?'¡Buen dominio de estos conceptos!':'Sigue practicando los servicios';
   $('quizResultDetail').textContent=`${right} respuestas correctas de ${total}. Este porcentaje mide tu práctica, no predice una calificación oficial del CLF-C02.`;
   $('quizReview').replaceChildren();
   answers.forEach((a,i)=>{
     const box=document.createElement('div');box.className='quiz-review-item';
     const title=document.createElement('strong');title.textContent=(a.correct?'✓ ':'✗ ')+(i+1)+'. '+a.question;
     const detail=document.createElement('span');detail.textContent='Tu respuesta: '+a.answer+' · Correcta: '+a.expected;
     const tip=document.createElement('p');tip.textContent=a.tip;
     box.append(title,detail,tip);$('quizReview').append(box);
   });show('quizResults');$('quizTrackFill').style.width='100%';
 }
 $('startQuiz').addEventListener('click',()=>{
   questions=buildQuestions();if(!questions.length)return;
   index=0;answers=[];mode=$('quizMode').value;show('quizPlay');renderQuestion();
 });
 $('nextQuiz').addEventListener('click',()=>{if(index+1===questions.length)finish();else{index++;renderQuestion()}});
 $('quitQuiz').addEventListener('click',()=>{if(confirm('¿Abandonar el simulacro actual? No se guardará el intento.'))show('quizSetup')});
 $('restartQuiz').addEventListener('click',()=>show('quizSetup'));
 $('reviewGuide').addEventListener('click',()=>switchTab('services'));
 updateStats();
})();
